#include <stdio.h>
#include <math.h>

#define W 2400
#define H 1800

static double clampd(double x){return x<0?0:(x>255?255:x);}

int main(void){
    /* scene */
    double Cx=0,Cy=1.5,Cz=0;                 /* camera */
    double Sx=0,Sy=1,Sz=5,R=1;               /* sphere */
    double Lx=1,Ly=1,Lz=1;                    /* light dir (to light) */
    double ln=sqrt(Lx*Lx+Ly*Ly+Lz*Lz); Lx/=ln;Ly/=ln;Lz/=ln;
    double aspect=(double)W/H;
    double amb=0.2, dif=0.8;
    double sbr=255,sbg=50,sbb=50;            /* sphere base color */

    FILE*f=fopen("reconstructed.ppm","wb");
    fprintf(f,"P6\n%d %d\n255\n",W,H);
    unsigned char*row=(unsigned char*)malloc(3*W);

    for(int py=0;py<H;py++){
        for(int px=0;px<W;px++){
            double u=(2.0*(px+0.5)/W-1.0)*aspect;
            double v=(1.0-2.0*(py+0.5)/H);
            double dx=u,dy=v,dz=1.0;
            double dn=sqrt(dx*dx+dy*dy+dz*dz); dx/=dn;dy/=dn;dz/=dn;

            double r,g,b;
            double tsph=1e30, tflr=1e30;

            /* sphere intersect */
            double ox=Cx-Sx, oy=Cy-Sy, oz=Cz-Sz;
            double bq=dx*ox+dy*oy+dz*oz;
            double cq=ox*ox+oy*oy+oz*oz-R*R;
            double disc=bq*bq-cq;
            if(disc>0){double t=-bq-sqrt(disc); if(t>1e-4) tsph=t;}

            /* floor plane y=0 */
            if(dy<-1e-9){double t=-Cy/dy; if(t>1e-4) tflr=t;}

            if(tsph<tflr && tsph<1e29){
                double Px=Cx+tsph*dx, Py=Cy+tsph*dy, Pz=Cz+tsph*dz;
                double nx=(Px-Sx)/R, ny=(Py-Sy)/R, nz=(Pz-Sz)/R;
                double nl=nx*Lx+ny*Ly+nz*Lz; if(nl<0)nl=0;
                double sh=amb+dif*nl;
                r=sbr*sh; g=sbg*sh; b=sbb*sh;
            } else if(tflr<1e29){
                double Px=Cx+tflr*dx, Pz=Cz+tflr*dz;
                int ip=(int)floor(Px)+(int)floor(Pz);
                int par=((ip%2)+2)%2;
                double base=par? 0.9:0.4;   /* odd->light */
                /* shadow: ray toward light hits sphere? */
                double sox=Px-Sx, soy=0-Sy, soz=Pz-Sz;
                double sb=Lx*sox+Ly*soy+Lz*soz;
                double sc=sox*sox+soy*soy+soz*soz-R*R;
                double sd=sb*sb-sc;
                int shadowed=0;
                if(sd>0){double st=-sb-sqrt(sd); if(st>1e-4) shadowed=1;}
                double nl=Ly; /* floor normal (0,1,0) */
                double sh=shadowed? amb : amb+dif*nl;
                double c=base*255.0*sh;
                r=g=b=c;
            } else {
                r=191.493-64.0187*dy;
                g=217.096-38.4212*dy;
                b=255.0;
            }
            row[px*3+0]=(unsigned char)(clampd(r)+0.5);
            row[px*3+1]=(unsigned char)(clampd(g)+0.5);
            row[px*3+2]=(unsigned char)(clampd(b)+0.5);
        }
        fwrite(row,1,3*W,f);
    }
    fclose(f);
    return 0;
}

